WITH valid AS (SELECT *, CEIL(temp_c) AS temp_c_whole FROM device_readings WHERE reading_ts > TO_TIMESTAMP('2025-09-01 02:00:00')), with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM valid), islands AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, temp_c_whole, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN temp_c_whole >= 75 THEN 'PREMIUM' ELSE 'STANDARD' END AS temp_c_whole_tier, device_code, STDDEV_SAMP(pressure) AS pressure_stddev, STDDEV_SAMP(humidity) AS humidity_stddev, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, GROUPING_ID() AS gid FROM islands GROUP BY GROUPING SETS ((CASE WHEN temp_c_whole >= 75 THEN 'PREMIUM' ELSE 'STANDARD' END, device_code), (CASE WHEN temp_c_whole >= 75 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) ORDER BY pressure_stddev NULLS LAST;
